def lees_getal(tekst: str) -> float:
    try:
        waarde = float(tekst)
    except ValueError as exc:
        print("Geen getal:", exc)
        return 0.0
    else:
        print("Gelukt")
        return waarde
    finally:
        print("Klaar met", repr(tekst))

print(lees_getal("3.5"))
print(lees_getal("drie"))

class OnvoldoendeVoorraad(Exception):
    """Er worden meer stuks gevraagd dan er op voorraad zijn."""

def reserveer(voorraad: int, aantal: int) -> int:
    if aantal <= 0:
        raise ValueError("aantal moet positief zijn")
    if aantal > voorraad:
        raise OnvoldoendeVoorraad(f"gevraagd {aantal}, nog {voorraad} over")
    return voorraad - aantal

print(reserveer(10, 4))
try:
    reserveer(2, 5)
except OnvoldoendeVoorraad as e:
    print("Lukt niet:", e)

class Factuur:
    BTW = 0.21

    def __init__(self, netto: float) -> None:
        self._netto = netto

    @property
    def bruto(self) -> float:
        return round(self._netto * (1 + self.BTW), 2)

    @classmethod
    def uit_bruto(cls, bruto: float) -> "Factuur":   # alternatieve constructor
        return cls(bruto / (1 + cls.BTW))

    @staticmethod
    def geldig(bedrag: float) -> bool:
        return bedrag >= 0

print(Factuur(200).bruto, Factuur.uit_bruto(242).bruto, Factuur.geldig(-5))

class Melder:
    def stuur(self, aan: str, tekst: str) -> None:
        raise NotImplementedError

class MailMelder(Melder):
    def stuur(self, aan: str, tekst: str) -> None:
        print(f"MAIL naar {aan}: {tekst}")

class SmsMelder(Melder):
    def __init__(self, afzender: str) -> None:
        super().__init__()                # constructor van de ouder
