import functools
import time

def timed(fn):
    @functools.wraps(fn)                   # behoud naam en docstring
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        resultaat = fn(*args, **kwargs)
        print(f"{fn.__name__} duurde {time.perf_counter() - start:.4f}s")
        return resultaat
    return wrapper

@timed
def optellen(n: int) -> int:
    """Telt 0 tot en met n-1 op."""
    return sum(range(n))

print(optellen(1_000_000), optellen.__name__)

import functools

@functools.lru_cache(maxsize=None)        # onthoud eerdere resultaten
def fib(n: int) -> int:
    return n if n < 2 else fib(n - 1) + fib(n - 2)

print(fib(80))
print(fib.cache_info().hits > 0)

