class MemoryStore:
    def __init__(self) -> None:
        self._tasks: list[str] = []
    def load(self) -> list[str]:
        return list(self._tasks)
    def save(self, tasks: list[str]) -> None:
        self._tasks = list(tasks)

class TaskService:
    def __init__(self, store) -> None:     # de service heeft een store
        self.store = store
    def add(self, title: str) -> None:
        tasks = self.store.load()
        tasks.append(title)
        self.store.save(tasks)

service = TaskService(MemoryStore())
service.add("Printer repareren")
print(service.store.load())

import json
from datetime import date

class StorageError(Exception):
    """Het takenbestand kan niet worden gelezen."""

def parse(text: str) -> list[dict]:
    try:
        rows = json.loads(text)
    except ValueError:
        raise StorageError("takenbestand is beschadigd")
    for row in rows:
        row["due"] = date.fromisoformat(row["due"]) if row["due"] else None
    return rows

print(parse('[{"title": "Printer", "due": "2026-09-15"}]'))
try:
    parse("{kapot")
except StorageError as e:
    print("StorageError:", e)
